199	<script>
200	import dataStore from '../../common/data-store'
201	
202	export default {
203	  data: {
204	    todayStats: {
205	      totalSwings: 0,
206	      duration: '00:00',
207	      calories: 0
208	    },
209	    shotDistribution: [
210	      { name: '高远球', count: 0, percentage: 10 },
211	      { name: '杀球', count: 0, percentage: 10 },
212	      { name: '平抽', count: 0, percentage: 10 },
213	      { name: '挑球', count: 0, percentage: 10 },
214	      { name: '吊球', count: 0, percentage: 10 }
215	    ],
216	    recentSessions: []
217	  },
218	
219	  onInit() {
220	    console.log('统计页面初始化')
221	    this.loadData()
222	  },
223	
224	  loadData() {
225	    // 从 data-store 加载今日统计
226	    const todayStats = dataStore.getTodayStats()
227	    this.todayStats = todayStats
228	
229	    // 加载击球类型分布
230	    const distribution = dataStore.getShotDistribution()
231	    const maxCount = Math.max(...Object.values(distribution), 1)
232	    this.shotDistribution = [
233	      { name: '高远球', count: distribution.highClear, percentage: (distribution.highClear / maxCount) * 100 },
234	      { name: '杀球', count: distribution.smash, percentage: (distribution.smash / maxCount) * 100 },
235	      { name: '平抽', count: distribution.drive, percentage: (distribution.drive / maxCount) * 100 },
236	      { name: '挑球', count: distribution.lift, percentage: (distribution.lift / maxCount) * 100 },
237	      { name: '吊球', count: distribution.drop, percentage: (distribution.drop / maxCount) * 100 }
238	    ]
239	
240	    // 加载最近会话
241	    const sessions = dataStore.sessions.slice(0, 5)
242	    this.recentSessions = sessions.map(s => ({
243	      date: this.formatDate(s.startTime),
244	      swings: s.swingCount,
245	      duration: this.formatDuration(s.duration),
246	      calories: s.calories
247	    }))
248	
249	    console.log('统计数据加载完成')
250	  },
251	
252	  formatDate(timestamp) {
253	    const date = new Date(timestamp)
254	    return `${date.getMonth() + 1}/${date.getDate()} ${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`
255	  },
256	
257	  formatDuration(seconds) {
258	    const mins = Math.floor(seconds / 60)
259	    const secs = seconds % 60
260	    return `${mins}:${secs.toString().padStart(2, '0')}`
261	  }
262	}
263	</script>
