/**
 * 传感器 Mock 数据生成器
 * 用于在没有真实传感器的环境下测试算法
 */

class MockSensor {
  constructor() {
    this.isRunning = false
    this.timer = null
    this.listeners = []
    this.swingPhase = 0 // 0: 静止, 1: 挥拍中
    this.swingCount = 0
  }

  /**
   * 生成 Mock 加速度数据
   */
  generateAccelData() {
    const baseGravity = { x: 0, y: 0, z: 9.8 }

    if (this.swingPhase === 0) {
      // 静止状态：仅有微小噪声
      return {
        x: baseGravity.x + (Math.random() - 0.5) * 0.5,
        y: baseGravity.y + (Math.random() - 0.5) * 0.5,
        z: baseGravity.z + (Math.random() - 0.5) * 0.5
      }
    } else {
      // 挥拍状态：模拟快速运动
      const swingIntensity = Math.sin(this.swingPhase * Math.PI) * 25
      return {
        x: baseGravity.x + swingIntensity * 0.3 + (Math.random() - 0.5) * 2,
        y: baseGravity.y + swingIntensity * 0.5 + (Math.random() - 0.5) * 2,
        z: baseGravity.z + swingIntensity * 0.8 + (Math.random() - 0.5) * 2
      }
    }
  }

  /**
   * 生成 Mock 陀螺仪数据
   */
  generateGyroData() {
    if (this.swingPhase === 0) {
      // 静止状态：仅有微小噪声
      return {
        x: (Math.random() - 0.5) * 5,
        y: (Math.random() - 0.5) * 5,
        z: (Math.random() - 0.5) * 5
      }
    } else {
      // 挥拍状态：模拟快速旋转
      const swingIntensity = Math.sin(this.swingPhase * Math.PI) * 400
      return {
        x: swingIntensity * 0.2 + (Math.random() - 0.5) * 20,
        y: swingIntensity * 0.4 + (Math.random() - 0.5) * 20,
        z: swingIntensity * 0.9 + (Math.random() - 0.5) * 20
      }
    }
  }

  /**
   * 启动 Mock 数据生成
   */
  start(callback, interval = 20) {
    if (this.isRunning) return

    this.isRunning = true
    this.swingPhase = 0

    this.timer = setInterval(() => {
      // 随机触发挥拍
      if (this.swingPhase === 0 && Math.random() < 0.02) {
        this.swingPhase = 0.1
        this.swingCount++
      }

      // 更新挥拍相位
      if (this.swingPhase > 0) {
        this.swingPhase += 0.15
        if (this.swingPhase >= 1) {
          this.swingPhase = 0
        }
      }

      const accel = this.generateAccelData()
      const gyro = this.generateGyroData()

      callback({
        accel,
        gyro,
        timestamp: Date.now()
      })
    }, interval)
  }

  /**
   * 停止 Mock 数据生成
   */
  stop() {
    this.isRunning = false
    if (this.timer) {
      clearInterval(this.timer)
      this.timer = null
    }
  }

  /**
   * 获取挥拍次数
   */
  getSwingCount() {
    return this.swingCount
  }

  /**
   * 重置
   */
  reset() {
    this.swingPhase = 0
    this.swingCount = 0
  }
}

export default new MockSensor()

