534	
535	    // 更新 UI
536	    this.totalStrokes++
537	    this.lastShotType = classification.typeName
538	
539	    // 更新击球统计
540	    const shotIndex = this.getShotIndex(classification.type)
541	    if (shotIndex >= 0) {
542	      this.shotDistribution[shotIndex].count++
543	      this.updateDistribution()
544	    }
545	
546	    // 记录到数据存储
547	    dataStore.recordSwing(classification.type)
548	
549	    // 震动反馈
550	    this.vibrate(50)
551	  },
552	
553	  handleHealthData(data) {
554	    if (data.type === 'heartRate') {
555	      this.heartRate = data.value
556	    } else if (data.type === 'calories') {
557	      this.calories = data.value
