562	  getShotIndex(type) {
563	    const types = ['highClear', 'smash', 'drive', 'lift', 'drop']
564	    return types.indexOf(type)
565	  },
566	
567	  updateDistribution() {
568	    const maxCount = Math.max(...this.shotDistribution.map(s => s.count), 1)
569	    this.shotDistribution = this.shotDistribution.map(item => ({
570	      ...item,
571	      percentage: (item.count / maxCount) * 100
572	    }))
573	  },
574	
575	  updateDuration() {
576	    if (!this.startTime) return
577	    const elapsed = Math.floor((Date.now() - this.startTime) / 1000)
578	    const mins = Math.floor(elapsed / 60).toString().padStart(2, '0')
579	    const secs = (elapsed % 60).toString().padStart(2, '0')
580	    this.duration = `${mins}:${secs}`
581	  },
